function colorHiddenStems(){const grid=document.querySelector('.mingtie.seven-cols');if(!grid)return;const cells=[...grid.children],label=cells.findIndex(el=>el.classList.contains('row-head')&&el.textContent.trim()==='藏干');if(label<0)return;for(let i=label+1;i<=label+7;i++){const box=cells[i]?.querySelector('.hidden');if(!box)continue;box.innerHTML=box.innerHTML.split('<br>').map(line=>{const stem=line.replace(/<[^>]*>/g,'').trim()[0];return stem&&E[stem]?`<span class="${E[stem]}">${stem}</span><span class="hidden-god">${line.replace(/<[^>]*>/g,'').trim().slice(1)}</span>`:line}).join('<br>')}}
