function embedPatternOverview(){const root=document.querySelector('#chartRoot'),base=root.querySelector('#base');if(!base||base.querySelector('.pattern-overview'))return;const all=JSON.parse(localStorage.getItem('qingshiji-archives')||'[]'),x=all.find(a=>a.id===localStorage.getItem('qingshiji-selected'));if(!x)return;const ps=pillars(new Date(x.trueSolar||x.solar)),v=patternOverview(ps),section=document.createElement('section');section.className='section-card pattern-overview';section.innerHTML=`<div class="section-head"><h2>命局总览</h2><small>月令格局 · 旺衰用神 · 纳音命</small></div><p class="pattern-note">以月令为提纲，综合透干、根气及生扶克泄进行结构初判；最终用神仍需结合调候、格局成败与岁运复核。</p><div class="pattern-grid"><article><span>八字十神格局</span><b>${v.pattern}</b><p>月令本气为${v.main}·${v.monthGod}，${v.透出?'本气已透干':'本气未透干'}。</p></article><article><span>日主用神</span><b class="${({木:'wood',火:'fire',土:'earth',金:'metal',水:'water'})[v.use]}">${v.use}</b><p>日主结构判为${v.strength}，生扶克泄差值 ${v.score}。</p></article><article><span>八字喜用神</span><b>${v.favors.map(e=>`<i class="${({木:'wood',火:'fire',土:'earth',金:'metal',水:'water'})[e]}">${e}</i>`).join('、')}</b><p>当前忌神倾向：${v.avoid.join('、')}；需结合寒暖燥湿复核。</p></article><article><span>六十甲子纳音命格</span><b>${v.命格}</b><p>年柱${ps[0]}对应纳音为${v.yearNayin}，民间简称“${v.命格}”。</p></article></div>`;const luck=[...base.children].find(el=>el.querySelector?.('h2')?.textContent==='流运');luck?base.insertBefore(section,luck):base.appendChild(section)}
