const nayinNotes={海中金:'金藏海底，象征潜质深藏、宜待时而发。重在积累，不宜急于求成。',炉中火:'如炉内之火，得木助则明，得器用则成；重在持续供养与节制。',大林木:'林木成片，重根基、环境与协同，得水土调和则生机充足。',路旁土:'承载道路之土，重秩序、实践与积累，宜有木水疏润。',剑锋金:'金性锋锐，重磨炼、决断与规范；过刚则折，需火炼水润。',山头火:'高处之火，显而易见，重传播与声势；忌无根虚燃。',涧下水:'溪涧之水，重源头与路径，宜得金生、汇流而成势。',城头土:'城垣之土，重边界、规则与守成；坚实则能护持。',白蜡金:'初成之金，尚待锻炼塑形，重学习、工艺与环境。',杨柳木:'柔木随风，适应力强，宜水土扶持，忌漂摇无根。',泉中水:'泉源清润，重持续供给与内在活力，宜疏导不宜壅塞。',屋上土:'覆护之土，重结构、责任与庇护，须有稳固承托。',霹雳火:'雷火迅疾，爆发力强，重时机与导向，忌骤起骤落。',松柏木:'耐寒常青，重原则、韧性与长期主义，得根则稳。',长流水:'水势绵长，重流通、远行与延续，忌阻滞泛滥。',砂中金:'金藏砂中，须淘洗磨炼方显价值，重识别与提纯。',山下火:'近地之火，重实际照明与温养，宜有木助而不过燥。',平地木:'平原之木，依赖土壤与群体环境，宜循序培育。',壁上土:'墙壁之土，重依附结构与防护，得木架火暖则成形。',金箔金:'薄金饰面，重精致、表达与价值呈现，需内在承托。',覆灯火:'灯烛之火，重专注、文明与指引，虽小而贵在持久。',天河水:'高天之水，意象宏阔，重理想、润泽与时势承接。',大驿土:'大道驿路之土，重承载、连接与资源流转。',钗钏金:'成器之金，重审美、人际与精工，宜珍惜而不宜过刚。',桑柘木:'实用之木，重生养、技艺与持续产出，宜水土相济。',大溪水:'溪流汇聚，行动与变化较强，宜有边界和方向。',沙中土:'土质松散，重凝聚、筑基与长期整合，忌根基不稳。',天上火:'日月之火，重光明、格局与普照，宜顺时而行。',石榴木:'秋实之木，外坚内丰，重成果、韧性与成熟后的释放。',大海水:'众水归海，容量与变化俱大，宜有格局，忌漫无边界。'};
const tenGodNotes={比肩:'同我同阴阳，代表自我、同辈、独立与竞争。得用时有主见、执行稳定；过旺时易固执、争夺资源。',劫财:'同我异阴阳，代表行动力、人际竞争、合作与分配。得用时敢担当、善联结；失衡时易冲动或财务分散。',食神:'我生同阴阳，代表才艺、表达、福气、产出与生活品质。得用时温和有创造力；过旺时易松散或泄身太过。',伤官:'我生异阴阳，代表突破、批判、技术、表达与不拘成法。得用时聪敏创新；失衡时易锋芒过露、与规则冲突。',偏财:'我克同阴阳，代表流动资源、市场机会、经营、人情与外财。得用时灵活慷慨；失衡时易逐利分心或财来财去。',正财:'我克异阴阳，代表稳定收入、责任、计划、资产与现实经营。得用时务实守信；失衡时易拘谨、劳碌或过度计较。',七杀:'克我同阴阳，代表压力、竞争、纪律、风险与决断。制化得宜可成执行力与权威；无制或攻身时压力较重。',正官:'克我异阴阳，代表规则、职位、责任、秩序与社会评价。得用时端正自律；受伤或过旺时易拘束、承压。',偏印:'生我同阴阳，代表非标准学习、洞察、策略、灵感与保护。得用时悟性强；失衡时易多虑、孤僻或夺食。',正印:'生我异阴阳，代表学习、资质、证书、照护、传统与承接。得用时稳健有涵养；过旺时易依赖或行动迟缓。',日主:'日干代表命局自身，是十神关系的参照中心。其旺衰不能仅凭数量判断，应综合月令、根气、透干和生克制化。'};
const patternNotes={建禄格:'月支临日干禄位，日主通常根气较足。取用重点在疏泄、制衡与格局流通，仍须判断是否透财官食伤。',羊刃格:'月令临羊刃，日主气势偏强而执行力突出。宜有官杀制刃或食伤泄秀，忌刃旺无制，但不能仅凭羊刃断凶。',比肩格:'月令本气为比肩，重自立、同辈与竞争，宜结合财官食伤是否透出判断成格方向。',劫财格:'月令本气为劫财，行动和竞争性较强，重点观察财星、官杀与食伤能否形成制化。',食神格:'月令食神当令，以泄秀生财为常见路径；喜身有根、食神清纯，忌偏印强力夺食。',伤官格:'月令伤官当令，重才华、技术与表达。可取伤官生财或伤官配印，需辨是否见官及有无救应。',偏财格:'月令偏财当令，重经营与流动资源。喜身能任财并见食伤生财，身弱财旺则宜印比扶身。',正财格:'月令正财当令，重稳定经营和现实责任。喜身财相停、官星有情，忌比劫争财或身弱不任。',七杀格:'月令七杀当令，重点在制化：食神制杀、印化杀或刃合杀均须条件完整；杀旺无制则压力偏重。',正官格:'月令正官当令，喜财印相辅、官星清纯和日主有根；忌伤官破官、官杀混杂，但须看全局救应。',偏印格:'月令偏印当令，重悟性、策略与特殊技能。喜偏印有制化或配官杀，忌枭神夺食造成结构阻滞。',正印格:'月令正印当令，重学习、承接与保护。喜官印相生或印得财官配合，印旺身强时宜财食疏通。'};
function nayinGrade(name){const upper=new Set(['剑锋金','松柏木','长流水','覆灯火','天河水','天上火','大海水','大林木','泉中水','大驿土']),lower=new Set(['海中金','路旁土','白蜡金','杨柳木','壁上土','金箔金','沙中土']);return upper.has(name)?'上等':lower.has(name)?'下等':'中等'}
function decorateNayin(){const grid=document.querySelector('.mingtie.seven-cols'),all=JSON.parse(localStorage.getItem('qingshiji-archives')||'[]'),x=all.find(a=>a.id===localStorage.getItem('qingshiji-selected'));if(!grid||!x)return;const d=new Date(x.trueSolar||x.solar),ps=pillars(d),now=new Date(),da=luck(ps,x,d),active=da.find((v,i)=>now.getFullYear()>=v.startYear&&(!da[i+1]||now.getFullYear()<da[i+1].startYear))||da[0],pillars7=[...ps,active.p,sex(now.getFullYear()-1984),monthPillar(now)],cells=[...grid.children],label=cells.findIndex(el=>el.classList.contains('row-head')&&el.textContent.trim()==='纳音');let tip=document.querySelector('#nayinTooltip');if(!tip){tip=document.createElement('div');tip.id='nayinTooltip';tip.className='shensha-tooltip nayin-tooltip';tip.setAttribute('role','tooltip');document.body.appendChild(tip)}const bind=(el,pillar,name)=>{el.classList.add('nayin-hover');el.tabIndex=0;el.dataset.pillar=pillar;el.dataset.nayin=name;if(el.dataset.nayinBound)return;el.dataset.nayinBound='1';const show=e=>{let n=el.dataset.nayin,p=el.dataset.pillar,g=nayinGrade(n);tip.innerHTML=`<b>${p} · ${n}<i>${g}参考</i></b><p>${nayinNotes[n]||'纳音用于观察干支组合的五行意象，应结合原局旺衰、月令格局与岁运综合理解。'}</p><small>品级依据传统生旺意象归纳，并非古籍统一定命等级。</small>`;tip.classList.add('show');move(e)},move=e=>{let r=el.getBoundingClientRect(),xx=e.clientX||r.left,yy=e.clientY||r.bottom,w=tip.offsetWidth||260,h=tip.offsetHeight||130;tip.style.left=Math.max(8,Math.min(xx+12,innerWidth-w-8))+'px';tip.style.top=Math.max(8,Math.min(yy+12,innerHeight-h-8))+'px'},hide=()=>tip.classList.remove('show');el.addEventListener('mouseenter',show);el.addEventListener('mousemove',move);el.addEventListener('mouseleave',hide);el.addEventListener('focus',show);el.addEventListener('blur',hide)};if(label>=0)pillars7.forEach((p,i)=>{let cell=cells[label+1+i];if(cell)bind(cell,p,nayin[Math.floor(idx(p)/2)])});const overview=document.querySelector('.pattern-overview .pattern-grid article:last-child>b');if(overview)bind(overview,overview.dataset.pillar||ps[0],overview.dataset.nayin||nayin[Math.floor(idx(ps[0])/2)])}
function decorateTenGods(){const grid=document.querySelector('.mingtie.seven-cols');if(!grid)return;const cells=[...grid.children],label=cells.findIndex(el=>el.classList.contains('row-head')&&el.textContent.trim()==='主星');let tip=document.querySelector('#tenGodTooltip');if(!tip){tip=document.createElement('div');tip.id='tenGodTooltip';tip.className='shensha-tooltip tengod-tooltip';tip.setAttribute('role','tooltip');document.body.appendChild(tip)}const bind=(el,name,isPattern=false)=>{el.classList.add('tengod-hover');el.tabIndex=0;if(el.dataset.tengodBound)return;el.dataset.tengodBound='1';const show=e=>{let raw=isPattern?el.textContent.trim():name,key=raw.endsWith('格')?raw:raw.replace(/^元男$|^元女$/,'日主'),note=isPattern?(patternNotes[key]||'以月令本气立格，再结合透干、会合、制化、旺衰与调候判断格局是否成立。'):(tenGodNotes[key]||tenGodNotes.日主);tip.innerHTML=`<b>${raw}<i>${isPattern?'十神格局':'十神'}</i></b><p>${note}</p><small>${isPattern?'格局名称是分析入口，成格、破格和救应必须结合全局。':'十神没有绝对吉凶，须结合位置、旺衰、组合和岁运判断。'}</small>`;tip.classList.add('show');move(e)},move=e=>{let r=el.getBoundingClientRect(),xx=e.clientX||r.left,yy=e.clientY||r.bottom,w=tip.offsetWidth||270,h=tip.offsetHeight||140;tip.style.left=Math.max(8,Math.min(xx+12,innerWidth-w-8))+'px';tip.style.top=Math.max(8,Math.min(yy+12,innerHeight-h-8))+'px'},hide=()=>tip.classList.remove('show');el.addEventListener('mouseenter',show);el.addEventListener('mousemove',move);el.addEventListener('mouseleave',hide);el.addEventListener('focus',show);el.addEventListener('blur',hide)};if(label>=0)for(let i=1;i<=7;i++){let cell=cells[label+i],name=cell?.textContent.trim();if(cell&&name)bind(cell,name)}const pattern=document.querySelector('.pattern-overview .pattern-grid article:first-child>b');if(pattern)bind(pattern,pattern.textContent.trim(),true)}
function tenGodShares(ps){const dm=ps[2][0],names=['比肩','劫财','食神','伤官','偏财','正财','七杀','正官','偏印','正印'],scores=Object.fromEntries(names.map(n=>[n,0]));ps.forEach((p,i)=>{scores[i===2?'比肩':god(dm,p[0])]+=1;const hs=hidden[p[1]],weights=hs.length===1?[1]:hs.length===2?[.7,.3]:[.6,.25,.15];hs.forEach((s,j)=>scores[god(dm,s)]+=weights[j])});const total=Object.values(scores).reduce((a,b)=>a+b,0);return names.map(name=>{const stem=[...S].find(s=>god(dm,s)===name),pct=total?Math.round(scores[name]/total*1000)/10:0;return{name,pct,stem,elementClass:E[stem]}})}
