function relationExplanation(r,ps,labels){const involved=r.at.map(i=>`${labels[i]}${ps[i]}`).join('、'),specific={'午未相合':['午未六合，午火生未土，常见亲和、承接与资源转化之象。能否合化为土，仍须结合月令、透干及是否受冲判断。','两股力量愿意靠近合作，火的行动逐渐落到土的现实结果。','宜把合作落实为明确责任和成果；若原局土过旺，则避免拖延、固守或过度消耗。'],'子丑相合':['子丑六合，水土相合，常含隐性牵引、现实整合之意，是否化土须审月令与助化条件。','想法与现实相互绑定，合作稳定但节奏可能偏慢。','明确边界与进度，避免湿土壅水造成情绪或执行阻滞。'],'寅亥相合':['寅亥六合化木意象较强，主生发、学习、远景与人际助力，仍须看木势是否得令。','水来生木，两方容易形成成长型合作。','适合学习、规划和开拓；木过旺时要控制目标扩张。'],'卯戌相合':['卯戌六合有化火之意，木火相引，常见表达、审美、人情与行动升温。','关系容易升温，并把想法转成行动。','保持理性边界，避免因情绪、人情或面子做过度承诺。'],'辰酉相合':['辰酉六合有化金之意，常见规则、技术、结果与资源收束。','分散资源开始归拢，事情趋向规范和结果。','适合整理制度与交付成果；金过旺时避免苛刻僵化。'],'巳申相合':['巳申六合有化水之意，同时本身也可能带刑意，合作与牵制常并存。','既互相吸引，也容易边合作边较劲。','先明确利益和权限；若同时见刑冲，应防反复与暗耗。']},base={合:['合表示两股干支力量相互吸引、牵制或趋向整合。合不等于必然合化，必须审月令、透干、助化及冲破。','双方更容易靠近、合作或彼此牵制。','利用协同但保留边界；确认是否出现争合、合绊或被冲破。'],冲:['冲表示方向相反、位置对立，常对应变化、移动、分离、调整或直接碰撞，不可一概断凶。','两股力量正面相撞，事情更容易变化。','主动预留调整空间，把冲动转化为迁移、改革和执行；避免硬碰硬。'],刑:['刑强调内部别扭、反复施压、自我消耗或规则摩擦，须结合旺衰及是否成局判断。','事情容易卡住、反复，心理或关系压力增加。','减少内耗，明确流程与责任；自刑尤其要避免重复纠结和过度用力。'],害:['害多指隐性妨碍、误解、暗耗与关系中的不协调，力量通常不如冲直接。','表面未必冲突，但容易暗中不顺。','加强沟通和核对，重要事项留痕，避免猜测与隐性消耗。'],会:['三会汇聚同一方气，季节性与方向性很强，成会时会显著增强对应五行。','多股力量聚到同一方向，某种五行明显增强。','顺势使用集中优势，同时检查该五行过旺是否破坏全局平衡。']}[r.type]||['该关系需结合全局判断。','两股干支发生作用。','结合旺衰和岁运复核。'],text=specific[r.label]||base;return{title:r.label,involved,detail:text[0],plain:text[1],advice:text[2]}}
