function enhanceBlindUsageInterpretation(){const panel=document.querySelector('[data-school-panel="blind"]'),list=panel?.querySelector('.blind-clue-list'),result=panel?.querySelector('.blind-result');if(!panel||!list||!result||panel.dataset.usageInterpretation==='1')return;const all=JSON.parse(localStorage.getItem('qingshiji-archives')||'[]'),x=all.find(a=>a.id===localStorage.getItem('qingshiji-selected'));if(!x)return;const base=pillars(new Date(x.trueSolar||x.solar)),dm=base[2][0],labels=['年柱','月柱','日柱','时柱','大运','流年','流月'],stems='甲乙丙丁戊己庚辛壬癸',branches='子丑寅卯辰巳午未申酉戌亥',clashStem={甲:'庚',庚:'甲',乙:'辛',辛:'乙',丙:'壬',壬:'丙',丁:'癸',癸:'丁'},clashBranch={子:'午',午:'子',丑:'未',未:'丑',寅:'申',申:'寅',卯:'酉',酉:'卯',辰:'戌',戌:'辰',巳:'亥',亥:'巳'};result.querySelector('span').textContent='用局象法释义';const explain=()=>{const active=list.querySelector('button.active');if(!active)return;const name=active.querySelector('b')?.textContent.trim()||'',method=active.querySelector('small')?.textContent.trim()||'',nodes=[...panel.querySelectorAll('.blind-node.active')],positions=nodes.map(n=>{const i=Number(n.dataset.index),s=n.querySelector('.blind-stem')?.textContent.trim(),b=n.querySelector('.blind-branch')?.textContent.trim();return`${labels[i]||'相关柱'}${s||''}${b||''}`}),chars=[...name].filter(c=>stems.includes(c)||branches.includes(c)),sameStem=chars.length>=2&&chars[0]===chars[1]&&stems.includes(chars[0]),isClash=name.includes('冲'),isTomb=name.includes('库藏')||name.includes('墓'),isVirtual=name.includes('虚邀')||name.includes('暗拱')||name.includes('拱'),isCombine=name.includes('合'),isPunish=name.includes('刑'),isHarm=name.includes('穿')||name.includes('害');let meaning='',symbol='',impact='',self='',verdict='';if(sameStem&&isClash){meaning=`${chars[0]}与${chars[1]}同为一干，传统干支关系中不构成“相冲”。它更接近同干并见、伏吟或同类力量叠加；当前名称应视为待校勘标签。`;symbol='同一十神或同类五行重复出现，象征同一种行为模式、资源或压力被反复放大。';impact=`当前参与位置为${positions.join('、')||'相关柱位'}。应根据${chars[0]}对日主${dm}所代表的十神为${god(dm,chars[0])}，判断重复的是助力还是负担，不能直接按冲局扣分。`;self='容易在相同议题上反复投入、坚持或内耗。若该十神为喜，则表现为能力集中；若为忌，则容易固执、重复犯错或同类压力叠加。';verdict=`${name}：名称需校勘，当前按“同干叠现”解释`}else if(isTomb){const activeBranches=nodes.map(n=>n.querySelector('.blind-branch')?.textContent.trim()).filter(b=>['辰','戌','丑','未'].includes(b)),branch=activeBranches[0]||base.find(p=>['辰','戌','丑','未'].includes(p[1])&&hidden[p[1]].some(s=>['比肩','劫财'].includes(god(dm,s))))?.[1]||'墓库',hiddenStems=hidden[branch]||[],gods=hiddenStems.map(s=>`${s}·${god(dm,s)}`),ownerIndex=base.findIndex(p=>p[1]===branch),owner=labels[ownerIndex]||'相关柱';meaning=`${name}表示相关十神被收存在${branch}库中。${branch}藏${gods.join('、')||'相关藏干'}；“入库”不是消失，而是有资源但暂未完全释放。`;symbol=name.includes('比劫')?'比劫代表同辈、人脉、竞争、合作及自我执行力；库藏则象征这些力量先积存在内部或固定圈层中。':'墓库象征收纳、封存、积累与等待条件开启，不能一见库就断吉凶。';impact=`此库落在${owner}，${ownerIndex>=2?'偏向主位，较容易成为命主自身可调用的潜藏力量':'偏向宾位，资源往往先在外部环境、家庭或他人一侧'}。是否真正为命主所用，要继续判断开库之岁运、库中之物是否为喜，以及开出后能否归主。`;self=name.includes('比劫')?'平时可能不显得特别依赖人脉，但合作、同辈资源与竞争意识会在特定岁运集中释放。库未启时宜积累团队规则和可信关系；有情冲刑开库时才适合扩大合作。':'容易把相关能力或需求先收住，外在表现较克制；遇到合适岁运才集中显现。';verdict=`${name}：有藏而待启，先辨库归${ownerIndex>=2?'主':'宾'}、再辨开出是否为喜`}else if(isVirtual){const target=(name.match(/虚邀(.)/)||name.match(/拱(.)/)||[])[1]||'虚神';meaning=`${name}属于“原局不见、由现有干支关系引出”的虚神结构。${target}不是原局实字，力量低于实见。`;symbol='代表潜在资源、隐性关系或尚未落地的机会，通常需要大运流年填实或引动后才明显。';impact=`当前由${positions.join('、')||'相关柱位'}形成线索。若${target}为命局所喜且引动后归主，可成为可用资源；若为忌或两端受破，则可能只是期待、牵制或落空。`;self='容易先感到某种机会或关系存在，但真正得到结果往往需要等待条件成熟。未填实时宜验证现实条件，不宜把潜在线索当成已经拥有。';verdict=`${name}：虚神候选，待岁运填实后再定成败`}else if(isClash){const a=chars[0],b=chars[1],valid=a&&b&&((stems.includes(a)&&clashStem[a]===b)||(branches.includes(a)&&clashBranch[a]===b));meaning=valid?`${a}${b}相冲表示两股方向相反的力量直接碰撞，使相关宫位、十神或事务发生移动、替换、分离或重组。`:`${name}被标记为冲用线索，但当前字符组合并非标准天干相冲或地支六冲，须按参与柱位重新校勘。`;symbol='冲不天然等于凶：冲开忌神、冲开所需之库可以有利；冲伤喜用根气或主位则多见压力与损耗。';impact=`作用位置为${positions.join('、')||'相关柱位'}。必须判断谁冲谁、被冲者是喜是忌，以及结果最终归主还是归宾。`;self='对应领域容易出现变化加速、决定被迫提前或关系重新分配。建议保留调整空间，避免在冲势最强时只凭情绪作决定。';verdict=`${name}：以“动、换、开、伤”四项逐一复核`}else if(isCombine){meaning=`${name}表示参与干支形成联结。合可能是合化、取得、合作，也可能是合绊、争合，不能见合即吉。`;symbol='象征资源连接、关系绑定、注意力被牵住或双方形成交换。';impact=`当前落在${positions.join('、')||'相关柱位'}。若化神得令、有根且为喜，联结更容易转成成果；若不化或争合，则可能降低原有力量的自由度。`;self='更容易通过合作、关系和资源整合完成事情，但应提前明确边界、利益和退出方式。';verdict=`${name}：先辨合化或合绊，再看成果是否归主`}else if(isPunish||isHarm){meaning=`${name}属于${isPunish?'刑':'穿害'}用线索，表示相关力量并非正面冲撞，而是反复制约、内部摩擦或隐性损耗。`;symbol=isPunish?'刑多取加工、反复、规则压力和难以一次解决。':'穿害多取暗中破坏、误会、条件不对称或慢性消耗。';impact=`作用位置为${positions.join('、')||'相关柱位'}。关键要看被损的是喜用还是忌神，以及损耗是否触及日时主位。`;self='容易在细节、沟通或长期消耗中感到不顺，应把模糊约定改成明确规则，并及早处理小问题。';verdict=`${name}：重在识别隐性代价与反复点`}else{meaning=`${name}是当前命盘命中的${method||'象法'}候选，表示参与干支之间形成了一条可观察的作用路径。`;symbol='象法用于把干支关系转化为人物、资源、事件和行为模式，但必须服从原局喜忌、宾主和体用。';impact=`当前涉及${positions.join('、')||'相关柱位'}。结构是否有效，要看作用后获得的结果能否回到日柱、时柱等主位并为命主所用。`;self='它提示命主在相关领域的常见做事方式，不等于固定命运；现实选择、环境与岁运会改变其表现程度。';verdict=`${name}：候选成立，仍需复核归主、归宾与岁运引动`}result.querySelector('span').textContent='用局象法释义';result.querySelector('b').textContent=verdict;result.querySelector('p').innerHTML=`<span class="blind-meaning-grid"><i><b>结构意思</b>${meaning}</i><i><b>象法代表</b>${symbol}</i><i><b>本盘影响</b>${impact}</i><i><b>对自身表现</b>${self}</i></span>`};list.addEventListener('click',()=>queueMicrotask(explain));panel.dataset.usageInterpretation='1'}
const refreshChartWithBlindUsage=refreshChart;refreshChart=function(){refreshChartWithBlindUsage();enhanceBlindUsageInterpretation()};
function removeSchoolChartDetailPanel(){document.querySelectorAll('.school-analysis .school-plain').forEach(panel=>{if(panel.querySelector(':scope>span')?.textContent.trim()==='命盘详解')panel.remove()})}
const refreshChartWithoutSchoolChartDetail=refreshChart;refreshChart=function(){refreshChartWithoutSchoolChartDetail();removeSchoolChartDetailPanel()};
let wenzhenShenshaSchema=null;
function wenzhenNayinElement(pillar){const value=nayin[Math.floor(idx(pillar)/2)]||'';return['木','火','土','金','水'].find(e=>value.endsWith(e))||''}
function wenzhenPositionValue(ps,pos,flow){if(pos>=1&&pos<=4)return ps[pos-1]?.[0]||'';if(pos===5||pos===6)return flow?.[0]||'';if(pos>=7&&pos<=10)return ps[pos-7]?.[1]||'';if(pos===11||pos===12)return flow?.[1]||'';if(pos>=13&&pos<=16)return ps[pos-13]||'';if(pos===17)return wenzhenNayinElement(ps[0]);if(pos===18)return ps.map(p=>p[0]).join('');if(pos===19)return flow||'';if(pos===20)return wenzhenNayinElement(ps[1]);if(pos===21)return wenzhenNayinElement(ps[2]);if(pos===22)return wenzhenNayinElement(ps[3]);if(pos>=23&&pos<=26)return ps[pos-23]||'';return''}
function wenzhenPositionColumn(pos){if(pos>=1&&pos<=4)return pos-1;if(pos>=7&&pos<=10)return pos-7;if(pos>=13&&pos<=16)return pos-13;if(pos>=23&&pos<=26)return pos-23;if(pos===17)return 0;if(pos===20)return 1;if(pos===21)return 2;if(pos===22)return 3;return 2}
function wenzhenSexAllowed(rule){if(!rule.sex||rule.sex==='0')return true;const gender=selectedGender();return rule.sex==='1'?gender==='男':rule.sex==='2'?gender==='女':true}
function wenzhenTokenMatch(expected,target){if(expected==null)return false;const clean=String(expected).replace(/[、,，\s/|]+/g,'');if(!clean)return false;return target.length===2?clean.includes(target):[...clean].includes(target)}
function wenzhenRuleHit(rule,ps,col,flow=null){if(!wenzhenSexAllowed(rule))return false;const mains=String(rule.main||'').split(',').map(Number).filter(Boolean),tags=String(rule.tags??'0').split(',').map(Number).filter(n=>!Number.isNaN(n)),data=rule.data||{};if(tags.includes(0)){return mains.some(pos=>{const value=wenzhenPositionValue(ps,pos,flow);if(pos===18)return Object.keys(data).some(sequence=>value.includes(sequence));return Object.prototype.hasOwnProperty.call(data,value)&&wenzhenPositionColumn(pos)===col})}const targetPositions=flow?tags.filter(pos=>[5,6,11,12,19].includes(pos)):tags.filter(pos=>wenzhenPositionColumn(pos)===col&&!([5,6,11,12,19].includes(pos)));if(!targetPositions.length)return false;return mains.some(pos=>{const base=wenzhenPositionValue(ps,pos,flow),expected=data[base];if(expected==null)return false;return targetPositions.some(targetPos=>wenzhenTokenMatch(expected,wenzhenPositionValue(ps,targetPos,flow)))})}
function fullShensha(ps,col){if(!wenzhenShenshaSchema?.rules?.length)return shensha(ps,col);const hits=wenzhenShenshaSchema.rules.filter(rule=>wenzhenRuleHit(rule,ps,col)).map(rule=>rule.name);return sortShenshaNames(hits).length?sortShenshaNames(hits):['—']}
function fullFlowShensha(ps,p){if(!wenzhenShenshaSchema?.rules?.length)return flowStars(ps,p);const hits=wenzhenShenshaSchema.rules.filter(rule=>wenzhenRuleHit(rule,ps,2,p)).map(rule=>rule.name);return sortShenshaNames(hits)}
async function initShensha(){try{[wenzhenShenshaSchema,shenshaProfiles,shenshaCatalog]=await Promise.all([fetch('/api/shensha-wenzhen.json').then(r=>{if(!r.ok)throw Error('wenzhen rules');return r.json()}),fetch('/api/shensha-profiles.json').then(r=>{if(!r.ok)throw Error('profiles');return r.json()}),fetch('/api/shensha-catalog.json').then(r=>{if(!r.ok)throw Error('catalog');return r.json()})]);fullRules=wenzhenShenshaSchema.rules||[]}catch(e){console.warn('data目录问真神煞算法暂不可用，已使用基础规则',e);wenzhenShenshaSchema=null;fullRules=[]}refreshChart()}
function markWenzhenDataShenshaSource(){const label=document.querySelector('.shensha-policy');if(label&&wenzhenShenshaSchema){label.textContent=`神煞：data 问真明文规则 · ${wenzhenShenshaSchema.rules_count||wenzhenShenshaSchema.rules.length}条`;label.title='当前八字命帖神煞已由 data/shensha_rules_wenzhen.json 位置编码规则表计算'}}
const refreshChartWithWenzhenSource=refreshChart;refreshChart=function(){refreshChartWithWenzhenSource();markWenzhenDataShenshaSource()};
refreshChart();initShensha();window.addEventListener('qingshiji-archive-selected',refreshChart);
